-- 227 (17/11/2026, lô 55): « DELF B1 · Đề 6 », phần ĐỌC viết lại khó hơn (văn bản dài hơn, câu hỏi về hàm ý).
-- Sinh bởi scripts/nhap/lo55_kho.mjs --cap B1 --de 6. Sửa thẳng, giữ id bài và id câu (cập nhật theo ord). Chạy lại an toàn.
-- lo22mvemyhx902j
update public.exercises set consigne = '<p>C''est l''été et il fait très chaud. Lisez les annonces et répondez aux questions.</p>', reading_text = '<p><strong>A. Musée des Beaux-Arts</strong> : salles climatisées, ouvert jusqu''à 21 h tous les jours en juillet et en août. Entrée 8 €, gratuite le premier dimanche du mois et pour les moins de 18 ans. Visites guidées « Peintres du soleil » le jeudi à 18 h, sur réservation. Café en terrasse ombragée dans le jardin du musée.</p><p><strong>B. Baignade au lac de Vassy</strong> : plage surveillée de 11 h à 19 h. Parking payant à l''entrée, mais une navette gratuite part de la gare toutes les trente minutes. Location de parasols sur place. Chiens interdits sur la plage. Baignade interdite en dehors des horaires de surveillance.</p><p><strong>C. Cinéma en plein air</strong> : chaque vendredi à 22 h, dans le parc municipal. Films en version originale sous-titrée. Gratuit. Pensez à apporter votre couverture et un vêtement chaud : la nuit, la température baisse vite près de la rivière. Annulé en cas d''orage. Programme complet affiché à l''entrée du parc chaque lundi.</p><p><strong>D. Grottes du Val-Noir</strong> : 13 °C toute l''année ! Départ toutes les heures, de 10 h à 17 h. Durée : 1 h 15. 9 € par adulte, 5 € par enfant. Chaussures fermées obligatoires, un pull conseillé. Visite déconseillée aux personnes qui ont peur des espaces fermés.</p><p><strong>E. Balade à vélo de nuit</strong> : le mercredi à 21 h 30, départ place du Marché. Parcours de 15 km sur pistes cyclables, à allure tranquille. Vélo, casque et lumières prêtés. 5 €. Âge minimum : 12 ans, accompagné d''un adulte jusqu''à 16 ans.</p>' where id = 'lo22mvemyhx902j';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Vous voulez avoir frais et découvrir de la peinture avec un guide. Vous choisissez…', '{"options":["A","C","D"]}'::jsonb, '{"answer":0}'::jsonb, 'A: « salles climatisées » và « Visites guidées « Peintres du soleil » ».'),
  (2, 'qcm', 'Vous voulez nager, mais vous n''avez pas de voiture. Vous choisissez…', '{"options":["D","E","B"]}'::jsonb, '{"answer":2}'::jsonb, 'B: « une navette gratuite part de la gare toutes les trente minutes ».'),
  (3, 'qcm', 'Votre fille de 13 ans adore le vélo, mais vous n''en avez pas. Vous choisissez…', '{"options":["B","E","A"]}'::jsonb, '{"answer":1}'::jsonb, 'E: « Vélo, casque et lumières prêtés » và « Âge minimum : 12 ans ».'),
  (4, 'qcm', 'Quelle activité ne convient pas à quelqu''un qui a peur d''être enfermé ?', '{"options":["C","D","E"]}'::jsonb, '{"answer":1}'::jsonb, 'D: « Visite déconseillée aux personnes qui ont peur des espaces fermés ».'),
  (5, 'qcm', 'Pourquoi faut-il un vêtement chaud au cinéma en plein air ?', '{"options":["Le parc ne propose pas de sièges.","Il fait frais la nuit près de la rivière.","Les films durent souvent plus de trois heures."]}'::jsonb, '{"answer":1}'::jsonb, '« la nuit, la température baisse vite près de la rivière ».')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo22mvemyhx902j' and q.ord = v.ord;

-- lo22mvemyhx902k
update public.exercises set consigne = '<p>Lisez l''article puis répondez aux questions.</p>', reading_text = '<p><strong>Été 2026 : la France n''a jamais eu aussi chaud</strong></p><p>Le verdict de Météo-France est tombé : l''été 2026 est le plus chaud jamais mesuré en France, devant 2003 et 2022, deux étés qui avaient pourtant marqué les esprits. Juillet a même été le mois le plus chaud depuis le début des relevés, en 1900. Partout dans le pays, des records sont tombés, y compris dans des régions que l''on croyait à l''abri des fortes chaleurs : Strasbourg a ainsi dépassé 40 °C, une première dans l''histoire de la ville.</p><p>La vague de chaleur de la fin juin a été particulièrement violente. Le 25 juin, 72 départements ont été placés en vigilance rouge canicule, une situation jamais vue depuis la création de ce système d''alerte, en 2004. Les écoles ont adapté leurs horaires, et de nombreuses villes ont ouvert des salles rafraîchies pour les personnes âgées. Ces mesures d''urgence, utiles, montrent toutefois les limites d''un pays qui réagit à la crise plus qu''il ne s''y prépare. Adapter des horaires ou ouvrir une salle pendant quelques jours ne transforme ni une ville ni un bâtiment.</p><p>Le bilan humain est lourd. Selon les premières estimations de Santé publique France, plus de 7 300 décès supplémentaires sont liés aux épisodes de chaleur de cet été. L''Île-de-France a été la région la plus touchée, en partie parce que les grandes villes, avec leur béton et leur goudron, gardent la chaleur la nuit. Or c''est justement la nuit que le corps a besoin de récupérer : quand la température ne redescend pas, la fatigue s''accumule de jour en jour, en particulier chez les plus fragiles. Ce constat rappelle que la chaleur n''est pas seulement une question de confort, mais aussi de santé publique.</p><p>À la chaleur s''est ajoutée la sécheresse : jamais les sols n''avaient été aussi secs, et des dizaines de départements ont dû limiter l''usage de l''eau. Pour beaucoup d''experts, cet été n''est pas une exception mais un aperçu de l''avenir. La question n''est donc plus seulement de réduire les émissions de gaz à effet de serre, mais aussi d''adapter nos villes, nos écoles et nos logements à des étés de plus en plus brûlants. Les deux efforts ne s''opposent pas, rappellent-ils : s''adapter sans réduire les émissions reviendrait à courir derrière un problème qui ne cesse de grandir.</p><p><p><small><em>Texte rédigé par FRACILE à partir de : Banque des Territoires, « Canicule, sécheresse, incendies : le bilan climatique hors normes de l''été 2026 » (banquedesterritoires.fr) ; Selectra, « Canicules de l''été 2026 : bilan » (selectra.info) ; données Météo-France et Santé publique France citées par ces articles.</em></small></p></p>' where id = 'lo22mvemyhx902k';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Que nous apprend l''article sur les étés 2003 et 2022 ?', '{"options":["Ils ont été plus meurtriers que 2026.","Ils restent aujourd''hui les plus chauds de l''histoire.","Ils ont été moins chauds que celui de 2026."]}'::jsonb, '{"answer":2}'::jsonb, '« l''été 2026 est le plus chaud jamais mesuré en France, devant 2003 et 2022 ».'),
  (2, 'qcm', 'Pourquoi le record de Strasbourg est-il remarquable ?', '{"options":["La ville n''avait jamais connu une telle chaleur.","Il a été mesuré au début du printemps.","C''est la ville la plus chaude de France."]}'::jsonb, '{"answer":0}'::jsonb, 'Strasbourg vượt 40 °C, « une première dans l''histoire de la ville », ở một vùng « que l''on croyait à l''abri des fortes chaleurs ».'),
  (3, 'vf', 'Le nombre de départements en vigilance rouge le 25 juin n''avait jamais été atteint depuis la création de ce système.', '{}'::jsonb, '{"answer":0,"justification":"une situation jamais vue depuis la création de ce système d''alerte"}'::jsonb, null),
  (4, 'qcm', 'Quelle critique l''auteur fait-il des mesures prises en juin ?', '{"options":["Elles ont été inutiles et coûteuses.","Elles répondent à la crise au lieu de l''anticiper.","Elles ont oublié les personnes âgées des campagnes."]}'::jsonb, '{"answer":1}'::jsonb, 'Các biện pháp « utiles », nhưng cho thấy « un pays qui réagit à la crise plus qu''il ne s''y prépare ».'),
  (5, 'qcm', 'Selon les premières estimations, combien de décès supplémentaires sont liés aux chaleurs ?', '{"options":["environ 730","plus de 73 000","plus de 7 300"]}'::jsonb, '{"answer":2}'::jsonb, '« plus de 7 300 décès supplémentaires sont liés aux épisodes de chaleur ».'),
  (6, 'qcm', 'Pourquoi la chaleur de la nuit est-elle particulièrement dangereuse ?', '{"options":["Les hôpitaux ferment pendant la nuit.","On boit moins d''eau quand on dort.","Le corps ne parvient pas à récupérer."]}'::jsonb, '{"answer":2}'::jsonb, '« c''est justement la nuit que le corps a besoin de récupérer : quand la température ne redescend pas, la fatigue s''accumule ».'),
  (7, 'vf', 'Malgré la chaleur, l''usage de l''eau n''a été limité dans aucun département.', '{}'::jsonb, '{"answer":1,"justification":"des dizaines de départements ont dû limiter l''usage de l''eau"}'::jsonb, null),
  (8, 'qcm', 'Selon les experts, faut-il choisir entre réduire les émissions et s''adapter ?', '{"options":["Oui, réduire les émissions suffit.","Non, les deux sont nécessaires.","Oui, il faut d''abord s''adapter."]}'::jsonb, '{"answer":1}'::jsonb, '« Les deux efforts ne s''opposent pas »: thích nghi mà không giảm phát thải là « courir derrière un problème qui ne cesse de grandir ».')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo22mvemyhx902k' and q.ord = v.ord;
